            let result = match special_owner {
                Some(owner) => {
                    note_special_route("door-special-arm", &class_for_dispatch, &name, &desc, true);
                    ctx.invoke_special_by_class_id(
                        owner,
                        &class_for_dispatch,
                        &name,
                        &desc,
                        &full_args,
                    )
                }
                None => {
                    note_special_route(
                        "door-special-arm",
                        &class_for_dispatch,
                        &name,
                        &desc,
                        false,
                    );
                    ctx.invoke_special(&class_for_dispatch, &name, &desc, &full_args)
                }
            };
